        vm.prank(caller);
        c.setOwner(newOwner);
        assertTrue(c.owner() == address(this));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(c)); // ensure caller is not the contract itself, which would bypass the admin check via msg.sender
        address originalOwner = c.owner();
        vm.prank(caller);
        c.setOwner(newOwner);
        // After a non-admin call, the owner should remain unchanged in the reference,
        // but in the mutant it changes to newOwner.
        assertEq(c.owner(), originalOwner, "Owner should not change when called by non-admin");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        address originalOwner = c.owner();
        vm.prank(caller);
        c.setOwner(newOwner);
        address currentOwner = c.owner();
        if (caller == address(uint160(uint256(keccak256(abi.encodePacked(address(c))))))) {
            assertTrue(currentOwner == newOwner);
        } else {
            assertTrue(currentOwner == originalOwner);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address oldOwner, address newOwner) public {
        vm.assume(caller != address(c)); // admin is the deployer, so we assume a different caller to avoid trivial equality
        vm.assume(oldOwner != newOwner);
        vm.prank(address(this)); // set initial owner to oldOwner using admin
        c.setOwner(oldOwner);
        vm.prank(caller);
        c.setOwner(newOwner);
        assertTrue(c.owner() == oldOwner);
    }
}
